  "check_code": "import re
import sqlite3
import hashlib
import json
from pathlib import Path

TARGET_ITEM = "UAC-AGI-2024-004"
LATER_ITEM = "UAC-AGI-2024-017"
ACTION_ID = "AB-RR-2024-021"
LATER_EVIDENCE = "DB-EVD-IFRS10-SCOPE-02"
ALLOWED_TARGET_CHANGES = {
    "decision_status",
    "management_response",
    "evidence_reference",
    "updated_at",
}
UNRELATED_COUNT = 69
UNRELATED_DIGEST = "e89bc359c40c08b2e6e8b3e4553c5abd1daee3ac6f04d7fe0683c84efe1ba68e"
TARGET_IMMUTABLE_DIGEST = "22f65c34ca51ca91bc80d7a9689595cbdaa2932b4773dc8b94a91a2868566a8c"


def _db_path(ws: Path) -> Path:
    return ws.parent / "system" / "diligent_boards_governance" / "state.db"


def _rows(path: Path) -> dict[str, dict]:
    con = sqlite3.connect(path)
    con.row_factory = sqlite3.Row
    try:
        return {
            row["agenda_item_id"]: dict(row)
            for row in con.execute("SELECT * FROM governance_agenda_items")
        }
    finally:
        con.close()


def _norm(value: object) -> str:
    return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()


def _digest(value: object) -> str:
    payload = json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode()
    return hashlib.sha256(payload).hexdigest()


def check_earlier_item_closed(ws: Path) -> dict:
    row = _rows(_db_path(ws)).get(TARGET_ITEM)
    if row is None:
        return {"score": 0, "detail": "the earlier target agenda item is missing"}

    response = _norm(row.get("management_response"))
    traceable = any(
        token in response
        for token in (
            _norm(LATER_ITEM),
            _norm(LATER_EVIDENCE),
            "march 7 2024",
            "later follow up",
        )
    )
    closure_meaning = "clos" in response and len(response) >= 30
    errors = []
    if row.get("decision_status") != "Action Closed":
        errors.append(f"decision_status is {row.get('decision_status')!r}")
    if row.get("evidence_reference") != LATER_EVIDENCE:
        errors.append(f"evidence_reference is {row.get('evidence_reference')!r}")
    if not (traceable and closure_meaning):
        errors.append("management_response does not concisely trace closure to the later follow-up")
    return {
        "score": 0 if errors else 1,
        "detail": "; ".join(errors) or "the earlier item is closed with traceable later-follow-up evidence",
    }


def check_stale_open_duplicate_removed(ws: Path) -> dict:
    con = sqlite3.connect(_db_path(ws))
    con.row_factory = sqlite3.Row
    try:
        rows = con.execute(
            """SELECT agenda_item_id, decision_status
               FROM governance_agenda_items
               WHERE action_id=? AND action_reference_status='Current'
               ORDER BY agenda_item_id""",
            (ACTION_ID,),
        ).fetchall()
    finally:
        con.close()
    item_ids = {row["agenda_item_id"] for row in rows}
    open_count = sum(row["decision_status"] == "Action Open" for row in rows)
    closed_count = sum(row["decision_status"] == "Action Closed" for row in rows)
    passed = item_ids == {TARGET_ITEM, LATER_ITEM} and open_count == 0 and closed_count == 2
    return {
        "score": 1 if passed else 0,
        "detail": (
            "the current action history contains two closed entries and no stale open duplicate"
            if passed
            else f"unexpected action history: ids={sorted(item_ids)}, open={open_count}, closed={closed_count}"
        ),
    }


def check_agenda_history_preserved(ws: Path) -> dict:
    current = _rows(_db_path(ws))
    target = current.get(TARGET_ITEM)
    if target is None:
        return {"score": 0, "detail": "the earlier target agenda item is missing"}
    unrelated = [current[item_id] for item_id in sorted(current) if item_id != TARGET_ITEM]
    immutable_target = {
        key: value for key, value in target.items() if key not in ALLOWED_TARGET_CHANGES
    }
    errors = []
    if len(unrelated) != UNRELATED_COUNT:
        errors.append(f"expected {UNRELATED_COUNT} unrelated rows, found {len(unrelated)}")
    if _digest(unrelated) != UNRELATED_DIGEST:
        errors.append("one or more unrelated agenda rows changed")
    if _digest(immutable_target) != TARGET_IMMUTABLE_DIGEST:
        errors.append("a protected field on the earlier target item changed")
    if errors:
        return {"score": 0, "detail": "; ".join(errors)}
    return {
        "score": 1,
        "detail": "the later follow-up, current action reference, and unrelated agenda history are unchanged",
    }
